"""Module for starting and stopping DCAP(now renamed to UTF-Lab) control service, if it was not started"""
import logging
import requests
from taf.collectors.core import ExecutionError
from taf.internal.managedobject import ManagedObject, Using
from taf.internal.execution.base import ExecutorFactory
from taf.internal.core import Factory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class DcapControllerCommandError(Exception):
    """
    Base Dcap controller command error.
    """


class DcapControllerCommandMissing(DcapControllerCommandError):
    """
    Dcap controller command is missing from the path.
    """


class DcapStarter(
        Using("executor"),
        ManagedObject):
    """This class is responsible for starting and stopping DCAP controller."""

    def __init__(self, http_library=requests, **kwargs):
        """Constructor

        :param http_library: HTTP library to use for checking if DCAP is running
        """
        super(DcapStarter, self).__init__(**kwargs)
        self._http_library = http_library
        self.should_terminate_dcap_on_teardown = False
        self.dcap_basic_controller_command = "utf_lab-controller"
        self.dcap_apigw_url = "http://localhost:4000/api/credentialRegion/v1"

    def _start_dcap_controller(self, timeout=300):
        self.executor.execute(f"timeout -v {timeout} {self.dcap_basic_controller_command} start --wait".encode("utf-8"))

    def _stop_dcap_controller(self, timeout=300):
        self.executor.execute(f"timeout -v {timeout} {self.dcap_basic_controller_command} stop".encode("utf-8"))

    def _check_if_dcap_controller_command_is_available(self):
        try:
            self.executor.execute(f"command -v {self.dcap_basic_controller_command}".encode("utf-8"))
        except ExecutionError as e:
            if e.exit_status == 1:
                raise DcapControllerCommandMissing(
                    f"command \"{self.dcap_basic_controller_command}\" is not found in the $PATH") from e
            raise

    def _is_dcap_running(self):
        try:
            dcap_apigw_response = self._http_library.get(self.dcap_apigw_url)
            is_running = dcap_apigw_response.status_code == requests.codes.ok
        except requests.ConnectionError:
            is_running = False

        return is_running

    def _setup(self):
        """
        Start the dcap controller, in case it is not running yet.
        If DCAP controller is already running, it won't be stopped in the stop_call of this class.
        """
        self._check_if_dcap_controller_command_is_available()
        if not self._is_dcap_running():
            self.should_terminate_dcap_on_teardown = True
            self._start_dcap_controller()
        else:
            logger.info("DCAP Already running, no need to start it!")

    def _teardown(self):
        """
        Stop the dcap controller, in case it was started by the DcapStarter.
        """
        if self.should_terminate_dcap_on_teardown:
            self._stop_dcap_controller()


class DcapStarterFactory(Factory):
    """Factory for DcapStarter"""

    _product_class = DcapStarter
    _existing_dcap_starters = {}

    def create(self, configuration, existing_arguments):
        key = self._get_key(configuration)
        if key in self._existing_dcap_starters:
            return self._existing_dcap_starters[key]
        else:
            dcap_starter = super(DcapStarterFactory, self).create(
                configuration=configuration,
                existing_arguments=existing_arguments)
            self._existing_dcap_starters[key] = dcap_starter
            return dcap_starter

    @staticmethod
    def _get_key(configuration):
        if "executor" in configuration and configuration['executor']['type'] == 'local':
            return 'local'
        raise AssertionError(f"unsupported configuration: {configuration!r}")

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(DcapStarterFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["executor"] = self._create_executor(
            executor_config=configuration["executor"])

    def _create_executor(self, executor_config):
        return ExecutorFactory().create(
            configuration=executor_config,
            existing_arguments={})
